fn get_first_elements(lst: Vec<Vec<i32>>) -> Vec<i32> {
    // Since we know each inner Vec<i32> is non‐empty,
    // it's safe to unwrap the first element.
    lst.iter()
        .map(|inner| inner.first().copied().unwrap())
        .collect()
}

